# ================= EPD 驱动 =================
W, H = 400, 300
RB = W // 8
N = RB * H

busy = machine.Pin(7, machine.Pin.IN, machine.Pin.PULL_UP)
rst = machine.Pin(8, machine.Pin.OUT, value=1)
dc = machine.Pin(9, machine.Pin.OUT, value=1)
cs = machine.Pin(10, machine.Pin.OUT, value=1)
spi = machine.SoftSPI(baudrate=2000000, polarity=0, phase=0,
                      sck=machine.Pin(12), mosi=machine.Pin(11), miso=machine.Pin(6))


def wait_busy(ms=60000):
    t = time.ticks_ms()
    while busy.value():
        if time.ticks_diff(time.ticks_ms(), t) > ms:
            raise RuntimeError("BUSY timeout")
        time.sleep_ms(5)


def cmd(c, data=None):
    dc.value(0)
    cs.value(0)
    spi.write(bytes((c,)))
    if data is not None:
        dc.value(1)
        spi.write(data)
    cs.value(1)
    dc.value(1)


def reset():
    rst.value(0)
    time.sleep_ms(10)
    rst.value(1)
    time.sleep_ms(10)
    wait_busy()


def init():
    reset()
    cmd(0x01, b"\x8f\x01\x00")   # 400行
    cmd(0x21, b"\x00\x00")       # 启用彩色RAM
    cmd(0x3C, b"\x05")           # border waveform
    cmd(0x11, b"\x03")           # 寻址模式
    cmd(0x18, b"\x80")           # 温度
    cmd(0x22, b"\xf7")           # 三色刷新
    time.sleep_ms(50)


def window():
    cmd(0x44, b"\x00\x31")
    cmd(0x45, b"\x00\x00\x2b\x01")
    cmd(0x4E, b"\x00")
    cmd(0x4F, b"\x00\x00")


def refresh():
    cmd(0x20)
    wait_busy()
    cmd(0x02)
    wait_busy()
    cmd(0x07, b"\x03")           # 深度休眠: 隔离接触噪声/省电; 下次 init() 硬复位自动唤醒


def conv_bw(fb):
    # fb: 位1=黑墨 -> 原地转换为面板格式(避免再分配15KB)
    if BW_WHITE == 0xFF:
        for i in range(N):
            fb[i] ^= 0xFF
    return fb


def conv_red(fr):
    # fr: 位1=红 -> 原地转换
    if RED_ON != 0xFF:
        for i in range(N):
            fr[i] ^= 0xFF
    return fr


def disc(fr, cx, cy, r):
    for dy in range(-r, r + 1):
        for dx in range(-r, r + 1):
            if dx * dx + dy * dy <= r * r:
                x, y = cx + dx, cy + dy
                if 0 <= x < W and 0 <= y < H:
                    fr[y * RB + (x >> 3)] |= 0x80 >> (x & 7)


def hline(fb, fr, x0, x1, y, color):
    """画水平线(2px厚). color='red' 用红RAM, 否则黑RAM."""
    tgt = fr if color == "red" else fb
    x0 = max(0, x0); x1 = min(W - 1, x1)
    for yy in (y, y + 1):
        if 0 <= yy < H:
            base = yy * RB
            for x in range(x0, x1 + 1):
                tgt[base + (x >> 3)] |= 0x80 >> (x & 7)


WK = ("一", "二", "三", "四", "五", "六", "日")
def week_str(wd):
    return "周" + WK[wd % 7]


def text_w(font, s):
    w = 0
    for ch in s:
        g = font.get(ch)
        w += g[0] if g else 9
    return w


def draw_text(fb, font, s, x, y):
    cx = x
    for ch in s:
        g = font.get(ch)
        if g is None:
            cx += 9
            continue
        w, h, dy = g[0], g[1], g[2]
        data = g[3:]
        bw = (w + 7) >> 3
        for ry in range(h):
            row = y + dy + ry
            if row < 0 or row >= H:
                continue
            base = row * RB
            for xb in range(bw):
                v = data[ry * bw + xb]
                if not v:
                    continue
                px = cx + xb * 8
                bi = px >> 3
                sh = px & 7
                if bi < RB:
                    fb[base + bi] |= v >> sh
                if sh and bi + 1 < RB:
                    fb[base + bi + 1] |= (v << (8 - sh)) & 0xFF
        cx += w


