def wx_zh(en):
    if en in WX_MAP:
        return WX_MAP[en]
    low = en.lower()
    for k, v in WX_MAP.items():
        if low.find(k.lower()) >= 0:
            return v
    return "多云"


def trend_zh(conds, current):
    seq = []
    for c in conds:
        z = wx_zh(c)
        if not seq or seq[-1] != z:
            seq.append(z)
    if not seq:
        return wx_zh(current)
    if len(seq) == 1:
        return seq[0]
    if seq[0] == seq[-1]:
        return seq[0]
    t = seq[0] + "转" + seq[-1]
    if len(t) > 6:
        return wx_zh(current)
    return t


def jval(seg, key):
    k = seg.find('"' + key + '"')
    if k < 0:
        return None
    i = seg.find(":", k)
    if i < 0:
        return None
    i += 1
    n = len(seg)
    while i < n and seg[i] in " \t\r\n":
        i += 1
    if i >= n:
        return None
    if seg[i] == '"':
        j = seg.find('"', i + 1)
        if j < 0:
            return None
        return seg[i + 1:j]
    j = i
    while j < n and seg[j] not in ",}\r\n \t":
        j += 1
    return seg[i:j]


def hourly_conds(body):
    i = body.find('"hourly"')
    if i < 0:
        return []
    end = body.find('"date"', i)
    seg = body[i:end] if end > 0 else body[i:]
    out = []
    p = 0
    while True:
        j = seg.find('"weatherDesc"', p)
        if j < 0:
            break
        v = jval(seg[j:], "value")
        if v:
            out.append(v)
        p = j + 13
    return out


def hhmm(s):
    s = s.strip()
    if s[-2:] in ("AM", "PM"):
        ap = s[-2:]
        s = s[:-2].strip()
        h, m = s.split(":")
        h = int(h) % 12
        if ap == "PM":
            h += 12
        return "%02d:%02d" % (h, int(m))
    return s[:5]


def http_get(url, timeout=12):
    """极简HTTP GET(仅HTTP), 返回 body 字符串; 失败返回 None(仅用于小响应, 如AQI)"""
    try:
        parts = url.split("/", 3)
        host = parts[2]
        path = "/" + parts[3] if len(parts) > 3 else "/"
        ai = socket.getaddrinfo(host, 80)[0][-1]
        s = socket.socket()
        s.settimeout(timeout)
        s.connect(ai)
        req = ("GET %s HTTP/1.0\r\nHost: %s\r\nUser-Agent: esp32-epd\r\n"
               "Connection: close\r\n\r\n" % (path, host))
        s.send(req.encode())
        buf = bytearray()
        while True:
            d = s.recv(1024)
            if not d:
                break
            buf += d
            if len(buf) > 65536:
                break
        s.close()
        i = bytes(buf).find(b"\r\n\r\n")
        if i < 0:
            return None
        return bytes(buf[i + 4:]).decode("utf-8", "ignore")
    except Exception as e:
        print("[http]", e)
        return None


def _url_encode(s):
    out = ""
    for ch in s:
        o = ord(ch)
        if o > 127:
            for b in ch.encode("utf-8"):
                out += "%%%02X" % b
        elif ch in " ":
            out += "%20"
        else:
            out += ch
    return out


def _kv(buf, key):
    """buf 中找 "key": "值" 或 "key":值; 返回 (值str, 结束pos); 不完整返回 None"""
    k = buf.find(b'"' + key + b'"')
    if k < 0:
        return None
    i = buf.find(b":", k)
    if i < 0:
        return None
    i += 1
    n = len(buf)
    while i < n and buf[i] in (32, 9, 13, 10):
        i += 1
    if i >= n:
        return None
    if buf[i] == 34:                      # 引号 -> 字符串值
        j = buf.find(b'"', i + 1)
        if j < 0:
            return None
        return buf[i + 1:j].decode("utf-8", "ignore"), j + 1
    j = i                                # 数字值
    while j < n and buf[j] not in (44, 125, 13, 10, 32, 9):
        j += 1
    if j >= n:
        return None
    return buf[i:j].decode(), j


def fetch_weather():
    """wttr.in j1 流式解析: 边收边抽取(字段顺序 current_condition->weather->astronomy->hourly),
    全程驻留缓冲 <2KB, 避免整包 23KB 响应撑爆内存"""
    gc.collect()
    url = "http://wttr.in/" + _url_encode(CITY) + "?format=j1"
    try:
        parts = url.split("/", 3)
        host = parts[2]
        path = "/" + parts[3] if len(parts) > 3 else "/"
        ai = socket.getaddrinfo(host, 80)[0][-1]
        s = socket.socket()
        s.settimeout(15)
        s.connect(ai)
        s.send(("GET %s HTTP/1.0\r\nHost: %s\r\nUser-Agent: esp32-epd\r\n"
                "Connection: close\r\n\r\n" % (path, host)).encode())
    except Exception as e:
        print("[http]", e)
        return None
    buf = b""
    temp = hum = cur = sr = ss = None
    conds = []
    stage = 0
    try:
        while stage < 9:
            chunk = s.recv(1024)
            if not chunk:
                break
            buf += chunk
            progress = True
            while progress:
                progress = False
                if stage == 0:                      # 等 current_condition(顺带跳过HTTP头)
                    i = buf.find(b'"current_condition"')
                    if i >= 0:
                        buf = buf[i:]
                        stage = 1
                        progress = True
                    elif len(buf) > 4096:
                        buf = buf[-256:]
                elif stage == 1:                    # humidity
                    r = _kv(buf, b"humidity")
                    if r:
                        hum = int(float(r[0]))
                        buf = buf[r[1]:]
                        stage = 2
                        progress = True
                elif stage == 2:                    # temp_C
                    r = _kv(buf, b"temp_C")
                    if r:
                        temp = int(float(r[0]))
                        buf = buf[r[1]:]
                        stage = 3
                        progress = True
                elif stage == 3:                    # 当前天气(weatherDesc 内的 value)
                    i = buf.find(b'"weatherDesc"')
                    if i >= 0:
                        r = _kv(buf[i:], b"value")
                        if r:
                            cur = r[0]
                            buf = buf[i + r[1]:]
                            stage = 4
                            progress = True
                elif stage == 4:                    # astronomy
                    i = buf.find(b'"astronomy"')
                    if i >= 0:
                        buf = buf[i:]
                        stage = 5
                        progress = True
                elif stage == 5:                    # sunrise
                    r = _kv(buf, b"sunrise")
                    if r:
                        sr = hhmm(r[0])
                        buf = buf[r[1]:]
                        stage = 6
                        progress = True
                elif stage == 6:                    # sunset
                    r = _kv(buf, b"sunset")
                    if r:
                        ss = hhmm(r[0])
                        buf = buf[r[1]:]
                        stage = 7
                        progress = True
                elif stage == 7:                    # hourly(当天)
                    i = buf.find(b'"hourly"')
                    if i >= 0:
                        buf = buf[i:]
                        stage = 8
                        progress = True
                elif stage == 8:                    # 逐条收 weatherDesc(到第二天或满8条即止)
                    i = 0
                    got = False
                    while True:
                        j = buf.find(b'"weatherDesc"', i)
                        if j < 0:
                            break
                        r = _kv(buf[j:], b"value")
                        if r is None:
                            break
                        conds.append(r[0])
                        i = j + r[1]
                        got = True
                    if got:
                        buf = buf[i:]
                        progress = True
                    if len(conds) >= 8 or buf.find(b'"date"') >= 0:
                        stage = 9
                        progress = True
    except Exception as e:
        print("[http]", e)
        try:
            s.close()
        except Exception:
            pass
        return None
    try:
        s.close()
    except Exception:
        pass
    if temp is None or hum is None:
        print("[wx] incomplete")
        return None
    return {"temp": temp, "cond": trend_zh(conds, cur or "Sunny"),
            "hum": hum, "sr": sr or "06:00", "ss": ss or "18:00"}


def fetch_aqi():
    """尽力获取AQI(需自建代理); 失败返回 None -> 界面隐藏AQI段"""
    if not AQI_URL:
        return None
    try:
        body = http_get(AQI_URL, 10)
        if not body:
            return None
        v = jval(body, "aqi")
        if v is None:
            return None
        return int(float(v))
    except Exception:
        return None


def aqi_level(a):
    if a <= 50:
        return "优"
    if a <= 100:
        return "良"
    if a <= 150:
        return "轻度污染"
    if a <= 200:
        return "中度污染"
    if a <= 300:
        return "重度污染"
    return "严重污染"


def save_cache(w):
    try:
        with open("/wcache.json", "w") as f:
            f.write('{"t":%d,"temp":%d,"cond":"%s","hum":%d,"sr":"%s","ss":"%s"}'
                    % (time.time(), w["temp"], w["cond"], w["hum"], w["sr"], w["ss"]))
    except Exception:
        pass


def load_cache():
    try:
        body = open("/wcache.json").read()
        return {"temp": int(jval(body, "temp")), "cond": jval(body, "cond"),
                "hum": int(jval(body, "hum")), "sr": jval(body, "sr"),
                "ss": jval(body, "ss")}
    except Exception:
        return None


# ================= 网络 =================
def wifi_up():
    w = network.WLAN(network.STA_IF)
    w.active(True)
    if w.isconnected():
        return True
    try:
        w.disconnect()
    except Exception:
        pass
    time.sleep(0.5)
    w.connect(SSID, PWD)
    t = time.ticks_ms()
    while not w.isconnected():
        if time.ticks_diff(time.ticks_ms(), t) > 20000:
            return False
        time.sleep_ms(300)
    return True


def ntp_sync():
    import ntptime
    for host in ("cn.pool.ntp.org", "ntp.aliyun.com", "pool.ntp.org"):
        try:
            ntptime.host = host
            ntptime.settime()
            print("[ntp] ok via", host)
            return True
        except Exception as e:
            print("[ntp] fail", host, e)
    return False


# ================= 主绘制 =================
def draw(lt, wx, aqi):
    gc.collect()
    fb = bytearray(N)     # 位1=黑墨
    fr = bytearray(N)     # 位1=红
    y, mo, d, hh, mi = lt[0], lt[1], lt[2], lt[3], lt[4]
    ok_time = y >= 2020

    # ---- 头部: 左=城市·日期  右=天气·红点·温度 ----
    if ok_time:
        hl = "%s %d年%d月%d日" % (CITY, y, mo, d)
        draw_text(fb, MID, hl, MARGIN_X, HEAD_Y)
        cond = wx["cond"]
        cw = text_w(MID, cond)
        tempw = text_w(MID, "%d°C" % wx["temp"])
        blockw = cw + 8 + 2 * DOT_R + 4 + tempw
        rx = W - MARGIN_X - blockw
        draw_text(fb, MID, cond, rx, HEAD_Y)
        disc(fr, rx + cw + 8 + DOT_R, HEAD_Y + 9, DOT_R)
        draw_text(fr, MID, "%d°C" % wx["temp"], rx + cw + 8 + 2 * DOT_R + 4, HEAD_Y)
    else:
        draw_text(fb, MID, "%s 时间同步中…" % CITY, MARGIN_X, HEAD_Y)
    # 头部分隔线
    hline(fb, fr, MARGIN_X, W - MARGIN_X, DIV_Y, DIV_COLOR)

    # ---- 大时钟(居中) ----
    if ok_time:
        hm = "%02d:%02d" % (hh, mi)
        gh = BIG["8"][1]
        tw = text_w(BIG, hm)
        draw_text(fb, BIG, hm, (W - tw) // 2, TIME_CY - gh // 2)
        wk = week_str(lt[6])
        draw_text(fb, MID, wk, (W - text_w(MID, wk)) // 2, WEEK_Y)
    else:
        draw_text(fb, MID, "时间同步中…", (W - text_w(MID, "时间同步中…")) // 2, TIME_CY - 9)

    # ---- 农历 · 节气/节日 ----
    if ok_time:
        t3 = lunar_str(y, mo, d)
        f = festival(y, mo, d)
        if f:
            t3 = t3 + " · " + f
        else:
            ct = current_term(y, mo, d)
            if ct:
                t3 = t3 + " · " + ct
        draw_text(fb, MID, t3, (W - text_w(MID, t3)) // 2, LUNAR_Y)

    # ---- AQI · 湿度 · 日出日落 (AQI超宽自动隐藏) ----
    if ok_time:
        parts = []
        if aqi is not None:
            parts.append("AQI %d %s" % (aqi, aqi_level(aqi)))
        parts.append("湿度 %d%%" % wx["hum"])
        parts.append("日出 %s 日落 %s" % (wx["sr"], wx["ss"]))
        t4 = " · ".join(parts)
        if text_w(MID, t4) > MAXW and aqi is not None:
            parts = parts[1:]
            t4 = " · ".join(parts)
        draw_text(fb, MID, t4, (W - text_w(MID, t4)) // 2, INFO_Y)

    init()
    window()
    cmd(0x24, conv_bw(fb))       # bytearray 可直接送 SoftSPI, 无需拷贝
    window()
    cmd(0x26, conv_red(fr))
    refresh()
    gc.collect()


# ================= 主流程 =================
def main():
    print("[boot] info clock start")
    WX = dict(WX_DEFAULT)
    aqi = None
    if wifi_up():
        print("[wifi] ok")
        ntp_sync()
        w = fetch_weather()
        if w:
            WX = w
            save_cache(w)
            print("[wx]", w)
        else:
            c = load_cache()
            if c:
                WX = c
                print("[wx] use cache")
        aqi = fetch_aqi()
    else:
        print("[wifi] FAILED -> 缓存/兜底数据")
        c = load_cache()
        if c:
            WX = c

    last_draw = None
    last_wx = time.time()
    last_ntp = time.time()
    err_n = 0
    while True:
        try:
            lt = time.localtime(time.time() + TZ)
            key = (lt[0], lt[1], lt[2], lt[3], lt[4] // CLOCK_STEP_MIN)
            now = time.time()
            if now - last_wx > WEATHER_MIN * 60:
                w = fetch_weather()
                if w:
                    WX = w
                    save_cache(w)
                last_wx = now
                aqi = fetch_aqi()
            if now - last_ntp > NTP_MIN * 60:
                if wifi_up():
                    ntp_sync()
                    last_ntp = now
            if key != last_draw:
                print("[draw]", "%04d-%02d-%02d %02d:%02d" % (lt[0], lt[1], lt[2], lt[3], lt[4]),
                      "free=%d" % gc.mem_free())
                draw(lt, WX, aqi)
                last_draw = key
                err_n = 0
            time.sleep(REFRESH_SEC)
        except Exception as e:
            import sys
            err_n += 1
            backoff = min(30 * err_n, 300)
            print("[err]", e, "-> 重绘退避", backoff, "s (第", err_n, "次)")
            sys.print_exception(e)
            time.sleep(backoff)


main()
